from bisect import bisect_right


def regex_search(pattern: str, text: str) -> bool:
    m = len(pattern)

    def parse_class_char(i: int) -> tuple[str, int]:
        if i >= m:
            raise ValueError("unexpected end of pattern")
        c = pattern[i]
        if c == "\\":
            if i + 1 >= m:
                raise ValueError("pattern ends with a single backslash")
            return pattern[i + 1], i + 2
        return c, i + 1

    def parse_class(i: int) -> tuple[tuple[int, int, bool], int]:
        # pattern[i] == '['
        i += 1
        neg = False
        if i < m and pattern[i] == "^":
            neg = True
            i += 1

        raw_ranges: list[tuple[int, int]] = []
        while True:
            if i >= m:
                raise ValueError("unterminated character class")
            if pattern[i] == "]":
                i += 1
                break

            first, i = parse_class_char(i)

            if (
                i < m
                and pattern[i] == "-"
                and i + 1 < m
                and pattern[i + 1] != "]"
            ):
                i += 1
                second, i = parse_class_char(i)
                if ord(first) > ord(second):
                    raise ValueError("invalid character class range")
                raw_ranges.append((ord(first), ord(second)))
            else:
                code = ord(first)
                raw_ranges.append((code, code))

        if not raw_ranges:
            raise ValueError("empty character class")

        raw_ranges.sort()
        ranges: list[tuple[int, int]] = []
        for s, e in raw_ranges:
            if not ranges or s > ranges[-1][1] + 1:
                ranges.append((s, e))
            else:
                if e > ranges[-1][1]:
                    ranges[-1] = (ranges[-1][0], e)

        return ((ranges, neg), i)

    def parse_atom(i: int) -> tuple[tuple, int]:
        if i >= m:
            raise ValueError("unexpected end of pattern")

        c = pattern[i]

        if c == "(":
            inner, i = parse_alt(i + 1)
            if i >= m or pattern[i] != ")":
                raise ValueError("unmatched parenthesis")
            return ("GROUP", inner), i + 1

        if c == "[":
            class_desc, i = parse_class(i)
            return ("CLASS", class_desc), i

        if c == "\\":
            if i + 1 >= m:
                raise ValueError("pattern ends with a single backslash")
            return ("CHAR", pattern[i + 1]), i + 2

        if c == ".":
            return ("DOT",), i + 1

        if c == "^":
            return ("ASSERT", 0), i + 1

        if c == "$":
            return ("ASSERT", 1), i + 1

        if c in "*+?":
            raise ValueError("quantifier has no preceding element")

        return ("CHAR", c), i + 1

    def parse_element(i: int) -> tuple[tuple, int]:
        node, i = parse_atom(i)

        if node[0] == "ASSERT":
            if i < m and pattern[i] in "*+?":
                raise ValueError("cannot apply quantifier to ^ or $")
            return node, i

        if i < m and pattern[i] in "*+?":
            q = pattern[i]
            i += 1
            if q == "*":
                return ("STAR", node), i
            if q == "+":
                return ("PLUS", node), i
            return ("OPTIONAL", node), i

        return node, i

    def parse_concat(i: int) -> tuple[tuple, int]:
        items = []
        while i < m and pattern[i] != "|" and pattern[i] != ")":
            node, i = parse_element(i)
            items.append(node)

        if not items:
            return ("EMPTY",), i
        if len(items) == 1:
            return items[0], i
        return ("CONCAT", items), i

    def parse_alt(i: int) -> tuple[tuple, int]:
        parts = []
        node, i = parse_concat(i)
        parts.append(node)

        while i < m and pattern[i] == "|":
            i += 1
            node, i = parse_concat(i)
            parts.append(node)

        if len(parts) == 1:
            return parts[0], i
        return ("ALT", parts), i

    def normalize_ranges(raw_ranges: list[tuple[int, int]]) -> tuple[tuple[int, ...], tuple[int, ...]]:
        raw_ranges.sort()
        ranges: list[tuple[int, int]] = []
        for s, e in raw_ranges:
            if not ranges or s > ranges[-1][1] + 1:
                ranges.append((s, e))
            else:
                if e > ranges[-1][1]:
                    ranges[-1] = (ranges[-1][0], e)

        starts = tuple(s for s, _ in ranges)
        ends = tuple(e for _, e in ranges)
        return starts, ends

    def class_match(payload: tuple[tuple[int, ...], tuple[int, ...], bool], ch: str) -> bool:
        starts, ends, neg = payload
        code = ord(ch)
        idx = bisect_right(starts, code) - 1
        inside = idx >= 0 and code <= ends[idx]
        return not inside if neg else inside

    eps: list[list[int]] = []
    preds: list[list[tuple]] = []
    asserts: list[list[tuple]] = []
    accept: list[bool] = []

    def new_state(is_accept: bool = False) -> int:
        state_id = len(eps)
        eps.append([])
        preds.append([])
        asserts.append([])
        accept.append(is_accept)
        return state_id

    def add_eps(src: int, dst: int) -> None:
        eps[src].append(dst)

    def add_assert(src: int, kind: int, dst: int) -> None:
        asserts[src].append((kind, dst))

    def add_pred(src: int, pred: tuple, dst: int) -> None:
        preds[src].append((pred, dst))

    def compile_node(node: tuple) -> tuple[int, int]:
        tag = node[0]

        if tag == "EMPTY":
            entry = new_state()
            exit_state = new_state()
            add_eps(entry, exit_state)
            return entry, exit_state

        if tag == "CHAR":
            entry = new_state()
            exit_state = new_state()
            add_pred(entry, (0, node[1]), exit_state)
            return entry, exit_state

        if tag == "DOT":
            entry = new_state()
            exit_state = new_state()
            add_pred(entry, (1, None), exit_state)
            return entry, exit_state

        if tag == "CLASS":
            raw_ranges, neg = node[1]
            starts, ends = normalize_ranges(raw_ranges)
            entry = new_state()
            exit_state = new_state()
            add_pred(entry, (2, (starts, ends, neg)), exit_state)
            return entry, exit_state

        if tag == "ASSERT":
            entry = new_state()
            exit_state = new_state()
            add_assert(entry, node[1], exit_state)
            return entry, exit_state

        if tag == "CONCAT":
            parts = node[1]
            entry, exit_state = compile_node(parts[0])
            for part in parts[1:]:
                next_entry, next_exit = compile_node(part)
                add_eps(exit_state, next_entry)
                exit_state = next_exit
            return entry, exit_state

        if tag == "ALT":
            entry = new_state()
            exit_state = new_state()
            for alt in node[1]:
                alt_entry, alt_exit = compile_node(alt)
                add_eps(entry, alt_entry)
                add_eps(alt_exit, exit_state)
            return entry, exit_state

        if tag == "GROUP":
            return compile_node(node[1])

        if tag == "STAR":
            inner_entry, inner_exit = compile_node(node[1])
            entry = new_state()
            exit_state = new_state()
            add_eps(entry, inner_entry)
            add_eps(entry, exit_state)
            add_eps(inner_exit, inner_entry)
            return entry, exit_state

        if tag == "PLUS":
            inner_entry, inner_exit = compile_node(node[1])
            entry = new_state()
            exit_state = new_state()
            add_eps(entry, inner_entry)
            add_eps(inner_exit, inner_entry)
            add_eps(inner_exit, exit_state)
            return entry, exit_state

        if tag == "OPTIONAL":
            inner_entry, inner_exit = compile_node(node[1])
            entry = new_state()
            exit_state = new_state()
            add_eps(entry, inner_entry)
            add_eps(entry, exit_state)
            add_eps(inner_exit, exit_state)
            return entry, exit_state

        raise ValueError("internal parser error")

    ast, end_pos = parse_alt(0)
    if end_pos != m:
        raise ValueError("unmatched parenthesis")

    start_state, final_state = compile_node(ast)
    accept[final_state] = True

    def epsilon_closure(states: set[int], pos: int) -> set[int]:
        active = set()
        stack = []

        for s in states:
            if s not in active:
                active.add(s)
                stack.append(s)

        at_start = pos == 0
        at_end = pos == len(text)

        while stack:
            s = stack.pop()

            for t in eps[s]:
                if t not in active:
                    active.add(t)
                    stack.append(t)

            for kind, t in asserts[s]:
                if (kind == 0 and at_start) or (kind == 1 and at_end):
                    if t not in active:
                        active.add(t)
                        stack.append(t)

        return active

    def move(states: set[int], ch: str) -> set[int]:
        nxt = set()

        for s in states:
            for pred, target in preds[s]:
                kind = pred[0]

                if kind == 0:
                    if pred[1] == ch:
                        nxt.add(target)
                elif kind == 1:
                    nxt.add(target)
                else:
                    if class_match(pred[1], ch):
                        nxt.add(target)

        return nxt

    text_len = len(text)
    active = epsilon_closure({start_state}, 0)

    for pos in range(text_len + 1):
        for s in active:
            if accept[s]:
                return True

        if pos == text_len:
            break

        nxt = move(active, text[pos])
        nxt.add(start_state)
        active = epsilon_closure(nxt, pos + 1)

    return False
